  /**
   * Unique symbol used as the key of the {@link PopulatedDocumentMarker}. Because it is a
   * `unique symbol` declared at module scope, the marker property is invisible at runtime and
   * cannot collide with any user-defined property.
   */
  const populatedDocumentMarker: unique symbol;

  /**
   * A type marker attached to populated document types. It carries both the populated raw document
   * type and the original depopulated raw document type as invisible metadata, so that
   * `toObject()`/`toJSON()` overloads can be resolved based on whether a document has been populated.
   *
   * The marker can be stripped from a populated document type via
   * `Omit<typeof doc, keyof PopulatedDocumentMarker<any, any>>`.
   */
  export type PopulatedDocumentMarker<PopulatedRawDocType, DepopulatedRawDocType> = {
    [populatedDocumentMarker]: [PopulatedRawDocType, DepopulatedRawDocType];
  };

  /**
   * Extracts the plain object type from a Document intersection type. If `T` extends some
   * `ObjectType & Document`, returns `FlatRecord<ObjectType>`; otherwise returns `T` unchanged.
   */
  export type ExtractDocumentObjectType<T> = T extends infer ObjectType & Document
    ? FlatRecord<ObjectType>
    : T;

  /**
   * Recursive helper that converts a populate `Paths` type (which may contain Document instances,
   * DocumentArrays, plain arrays, or nested objects) into a plain raw document type suitable for
   * use as the populated raw doc type.
   */
  export type PopulatePathToRawDocType<T> = T extends Document
    ? ExtractDocumentObjectType<T>
    : T extends Types.DocumentArray<infer Item>
      ? ExtractDocumentObjectType<Item>[]
      : T extends Array<infer Item>
        ? PopulatePathToRawDocType<Item>[]
        : T extends Record<string, any>
          ? { [K in keyof T]: PopulatePathToRawDocType<T[K]> }
