[metadata] {"type": "create", "filePath": "/workspace/repo/scratch/populate_check.ts", "content": "import mongoose, { Schema, model, Types, HydratedDocFromModel } from 'mongoose';

function ExpectType<T>(_v: T): void {}

async function childrenPopulate() {
  interface IChild { name: string; }
  const childSchema = new Schema<IChild>({ name: String });
  const ChildModel = model<IChild>('Child2', childSchema);

  interface IParent { children: Types.ObjectId[]; name: string; }
  const parentSchema = new Schema<IParent>({
    children: [{ type: Schema.Types.ObjectId, ref: 'Child2' }],
    name: String
  });
  const ParentModel = model<IParent>('Parent2', parentSchema);

  const doc = await ParentModel.findOne().orFail();

  type ChildDoc = HydratedDocFromModel<typeof ChildModel>;
  const populated = await doc.populate<{ children: Types.DocumentArray<ChildDoc> }>('children');

  // (a) no options -> populated shapes
  const obj = populated.toObject();
  ExpectType<string>(obj.children[0].name);

  // (c) depopulate: true only -> original ObjectId
  const dep = populated.toObject({ depopulate: true });
  ExpectType<Types.ObjectId>(dep.children![0]);

  // (d) depopulate + flattenObjectIds -> string
  const depFlat = populated.toObject({ depopulate: true, flattenObjectIds: true });
  ExpectType<string>(depFlat.children![0]);

  // strip marker -> base behavior -> ObjectId array
  type Stripped = Omit<typeof populated, keyof mongoose.PopulatedDocumentMarker<any, any>>;
  const strippedDoc = populated as unknown as Stripped;
  const strippedObj = strippedDoc.toObject();
  ExpectType<Types.ObjectId>(strippedObj.children![0]);

  // populated result NOT assignable to original hydrated model type
  // @ts-expect-error populated doc should not be assignable to un-populated hydrated type
  const notAssignable: HydratedDocFromModel<typeof ParentModel> = populated;
  void notAssignable;
}

async function queryPopulate() {
  interface Parent { child?: Types.ObjectId; name?: string; }
  const ParentModel = model<Parent>('QParent', new Schema({ child: { type: Schema.Types.ObjectId, ref: 'QChild' }, name: String }));
  interface Child { name: string; }
  model<Child>('QChild', new Schema({ name: String }));

  const doc = await ParentModel.findOne({}).populate<{ child: Child }>('child').orFail();
  ExpectType<string>(doc.child.name);
  const docObject = doc.toObject();
  ExpectType<string>(docObject.child.name);
}

void childrenPopulate;
void queryPopulate;
